logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(name)s: %(message)s")
logger = logging.getLogger(__name__)


HTML = r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Маркетплейсы</title><style>
:root{--bg:#0b1020;--panel:#151c30;--line:#29334d;--text:#eef3ff;--muted:#94a3bd;--a:#6ea8fe;--good:#38d39f;--bad:#ff6b7a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui}header{padding:24px 4vw;border-bottom:1px solid var(--line);display:flex;gap:20px;align-items:end;justify-content:space-between}h1{margin:0;font-size:25px}main{padding:24px 4vw}.filters{display:flex;gap:10px;flex-wrap:wrap}input,button{background:#11182a;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:10px}button{background:var(--a);color:#061020;font-weight:700;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:14px;margin:18px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:17px}.card h3{margin:0 0 12px;color:var(--muted);font-size:12px;text-transform:uppercase}.big{font-size:25px;font-weight:750}.row{display:flex;justify-content:space-between;align-items:start;gap:16px;margin-top:10px;color:var(--muted)}.row b{color:var(--text);text-align:right;max-width:62%}section{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;margin-top:16px}h2{margin:0 0 16px;font-size:17px}.chart-scroll{overflow-x:auto;padding-top:34px}.bars{display:flex;align-items:end;gap:8px;height:240px;min-width:max-content;border-bottom:1px solid var(--line)}.chart-item{width:74px;height:100%;display:flex;flex-direction:column;justify-content:end;align-items:center}.bar{width:56px;background:linear-gradient(180deg,var(--a),#4169b1);border-radius:6px 6px 0 0;position:relative;min-height:8px}.bar.empty{background:#313a50;height:8px!important}.bar-value{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translateX(-50%);text-align:center;white-space:nowrap;font-size:11px;color:var(--text)}.bar-value small{display:block;color:var(--muted);margin-top:2px}.day{height:24px;padding-top:6px;color:var(--muted);font-size:11px}.legend{color:var(--muted);margin-top:10px}.error{color:var(--bad)}@media(max-width:600px){header{align-items:start;flex-direction:column}.grid{grid-template-columns:1fr}.row{display:block}.row b{display:block;max-width:none;text-align:left;margin-top:3px}.chart-item{width:66px}.bar{width:50px}}
</style></head><body><header><div><h1>МАРКЕТПЛЕЙСЫ</h1><div style="color:var(--muted)">WB · Ozon · Яндекс Маркет</div></div><div class="filters"><input id="from" type="date"><input id="to" type="date"><button onclick="load()">Обновить</button></div></header><main><div id="status"></div><div class="grid" id="markets"></div><div class="grid" id="secondary"></div><section><h2>Заказы по дням / 每日订单</h2><div class="chart-scroll"><div class="bars" id="chart"></div></div><div class="legend">Количество и сумма заказов за каждый календарный день / 每个日历日的订单数量和金额</div></section></main><script>
const names={wb:'Wildberries',ozon:'Ozon',yandex_market:'Яндекс Маркет'};
const rub=n=>n===null||n===undefined?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(n||0))+' ₽';
const num=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(n||0));
const delta=(now,old,suffix='')=>{if(now===null||now===undefined)return '';now=Number(now);old=Number(old||0);if(!old)return now?` (новое / 新增)`:'';let value=(now-old)/Math.abs(old)*100;return ` (${value>=0?'+':''}${value.toFixed(1)}%${suffix})`};
const pair=(value,old)=>`${num(value.orders)} шт. / ${rub(value.orders_amount)}${delta(value.orders,old.orders,' шт.')}${delta(value.orders_amount,old.orders_amount,' ₽')}`;
async function load(){let q=new URLSearchParams({from:from.value,to:to.value});status.textContent='Загрузка…';try{let d=await fetch('/api/summary?'+q);if(!d.ok)throw Error(await d.text());d=await d.json();from.value=d.period.from;to.value=d.period.to;let errors=[];markets.innerHTML=Object.entries(d.marketplaces).map(([k,v])=>{let p=d.previous_marketplaces[k]||{},a=d.ads[k]||{},pa=d.previous_ads[k]||{},s=d.stocks[k]||{},ps=d.previous_stocks[k]||{};if(v.error)errors.push(names[k]+': '+v.error);let roas=a.spend?a.attributed_revenue/a.spend:null,proas=pa.spend?pa.attributed_revenue/pa.spend:null;let finance=v.revenue===null?'<div class="row error"><span>Финансы / 财务</span><b>нет данных / 暂无数据</b></div>':`<div class="row"><span>Выручка / 收入</span><b>${rub(v.revenue)}${delta(v.revenue,p.revenue)}</b></div><div class="row"><span>Расходы без себестоимости / 不含成本的支出</span><b>${rub(v.expenses)} · ${Number(v.expense_ratio||0).toFixed(1)}%${delta(v.expenses,p.expenses)}</b></div><div class="row"><span>Себестоимость выкупов / 已售商品成本</span><b>${rub(v.cost_of_goods)} · покрытие ${Number(v.cost_coverage||0).toFixed(0)}%${delta(v.cost_of_goods,p.cost_of_goods)}</b></div><div class="row"><span>Прибыль / 利润</span><b>${rub(v.profit)} · ${Number(v.profit_margin||0).toFixed(1)}%${delta(v.profit,p.profit)}</b></div>`;let adSpendLabel=k==='ozon'?'Рекламные кампании / 广告活动':'Реклама / 广告';let adRevenueLabel=k==='ozon'?'Атрибутированная сумма заказов / 广告归因订单额':'Выручка рекламы / 广告收入';return `<div class="card"><h3>${names[k]}</h3><div class="big">${rub(v.revenue)}</div><div class="row"><span>Заказы / 订单</span><b>${pair(v,p)}</b></div><div class="row"><span>Отмены / 取消</span><b>${num(v.cancelled)} шт. / ${rub(v.cancelled_amount)} · ${Number(v.cancel_rate||0).toFixed(1)}%${delta(v.cancelled,p.cancelled,' шт.')}${delta(v.cancelled_amount,p.cancelled_amount,' ₽')}</b></div><div class="row"><span>Выкупленные товары / 已购商品</span><b>${num(v.buyouts)} шт. / ${rub(v.buyouts_amount)}${delta(v.buyouts,p.buyouts,' шт.')}${delta(v.buyouts_amount,p.buyouts_amount,' ₽')}</b></div>${finance}<div class="row"><span>Остаток / 库存</span><b>${num(s.units)} шт. / ${rub(s.cost_value)}${delta(s.units,ps.units,' шт.')}${delta(s.cost_value,ps.cost_value,' ₽')}</b></div><div class="row"><span>${adSpendLabel}</span><b>${rub(a.spend)}${delta(a.spend,pa.spend)}</b></div><div class="row"><span>${adRevenueLabel}</span><b>${rub(a.attributed_revenue)}${delta(a.attributed_revenue,pa.attributed_revenue)}</b></div><div class="row"><span>ROAS / 广告投资回报率</span><b>${roas===null?'—':roas.toFixed(2)}${delta(roas,proas)}</b></div></div>`}).join('');let rows=Object.values(d.marketplaces),prev=Object.values(d.previous_marketplaces),covered=rows.filter(v=>v.revenue!==null).length,total=rows.reduce((x,v)=>x+Number(v.revenue||0),0),oldTotal=prev.reduce((x,v)=>x+Number(v.revenue||0),0),profit=rows.reduce((x,v)=>x+Number(v.profit||0),0),oldProfit=prev.reduce((x,v)=>x+Number(v.profit||0),0);secondary.innerHTML=`<div class="card"><h3>Подтверждённая общая выручка / 已确认总收入 · ${covered}/3</h3><div class="big">${rub(total)}${delta(total,oldTotal)}</div></div><div class="card"><h3>Подтверждённая общая прибыль / 已确认总利润 · ${covered}/3</h3><div class="big">${rub(profit)}${delta(profit,oldProfit)}</div></div>`;let days={},cursor=new Date(d.period.from+'T00:00:00'),last=new Date(d.period.to+'T00:00:00');while(cursor<=last){let key=[cursor.getFullYear(),String(cursor.getMonth()+1).padStart(2,'0'),String(cursor.getDate()).padStart(2,'0')].join('-');days[key]={orders:0,amount:0};cursor.setDate(cursor.getDate()+1)}d.series.forEach(x=>{let item=days[x.day]||(days[x.day]={orders:0,amount:0});item.orders+=Number(x.orders||0);item.amount+=Number(x.revenue||0)});let max=Math.max(1,...Object.values(days).map(x=>x.orders));chart.innerHTML=Object.entries(days).map(([day,v])=>{let empty=!v.orders,height=empty?8:Math.max(12,v.orders/max*100);return `<div class="chart-item"><div class="bar${empty?' empty':''}" style="height:${height}%"><div class="bar-value">${num(v.orders)} шт.<small>${rub(v.amount)}</small></div></div><div class="day">${day.slice(8,10)}.${day.slice(5,7)}</div></div>`}).join('');status.innerHTML=`Период / 期间 ${d.period.from} — ${d.period.to}; сравнение / 对比 ${d.previous_period.from} — ${d.previous_period.to}`+(errors.length?'<p class="error">Часть данных недоступна: '+errors.join('; ')+'</p>':'')}catch(e){status.innerHTML='<p class="error">'+e.message+'</p>'}}
let now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');to.value=today;from.value=today;load();</script></body></html>'''


class Handler(BaseHTTPRequestHandler):
    service = DashboardService()
    def do_GET(self):
        parsed = urlparse(self.path)
        try:
            if parsed.path == "/health": self._send(200, b'{"status":"ok"}', "application/json")
            elif parsed.path == "/api/summary":
                query = parse_qs(parsed.query); payload = self.service.summary((query.get("from") or [None])[0], (query.get("to") or [None])[0])
                self._send(200, json.dumps(payload, ensure_ascii=False, default=str).encode(), "application/json")
            elif parsed.path == "/": self._send(200, HTML.encode(), "text/html; charset=utf-8")
            else: self._send(404, b"not found", "text/plain")
        except (ValueError, TypeError) as exc: self._send(400, str(exc).encode(), "text/plain; charset=utf-8")
        except Exception:
            logger.exception("Dashboard request failed: %s", self.path)
            self._send(500, b"internal error", "text/plain")
    def _send(self, status, content, content_type):
        self.send_response(status); self.send_header("Content-Type", content_type); self.send_header("Content-Length", str(len(content))); self.send_header("Cache-Control", "no-store"); self.send_header("X-Content-Type-Options", "nosniff"); self.send_header("X-Frame-Options", "DENY"); self.end_headers(); self.wfile.write(content)
    def log_message(self, fmt, *args): return


if __name__ == "__main__":
    if DASHBOARD_HOST not in {"127.0.0.1", "::1"}: raise RuntimeError("DASHBOARD_HOST must remain loopback-only")
    ThreadingHTTPServer((DASHBOARD_HOST, DASHBOARD_PORT), Handler).serve_forever()
